92	func TestAdminFromStoreUsesTheStoredAdminPassword(t *testing.T) {
93		b := provisioned(t)
94		before := len(b.nexus.Requests())
95	
96		ctx := context.Background()
97		c, sec, err := adminFromStore(ctx, b.nexus.URL(), b.store)
98		if err != nil {
99			t.Fatalf("adminFromStore: %v", err)
100		}
101		defer c.closeIdle()
102		b.requireQuiet(nil)
103	
104		if sec.AdminPassword != storedAdmin {
105			t.Error("the returned secrets do not carry the stored admin password")
106		}
107		if want := b.store.current().PullPassword; want == "" || sec.PullPassword != want {
108			t.Error("the returned secrets do not carry the bench-pull password the store holds")
109		}
110		if got := len(b.nexus.Requests()); got != before {
111			t.Errorf("adminFromStore sent %d request(s), want none", got-before)
112		}
113	
114		// The client really authenticates as admin with that password.
115		if _, err := b.list(c, dockerProxyRepository); err != nil {
116			t.Fatalf("listComponents with the stored client: %v", err)
117		}
118		reqs := b.requestsFrom(before)
119		if len(reqs) == 0 || reqs[0].User != adminUserID || reqs[0].EmptyPassword {
120			t.Errorf("first call = %+v, want Basic auth as %s with a password", reqs, adminUserID)
121		}
122		if b.ip.reads != 0 {
123			t.Errorf("the initial password of the pod was read %d time(s)", b.ip.reads)
124		}
125	}
