127	func TestAdminFromStoreNeverFallsBackToTheInitialPassword(t *testing.T) {
128		// The instance still has its initial password and the store holds another
129		// one: a client that fell back to the pod's password would succeed.
130		b := newBench(t)
131		b.store.preset(Secrets{AdminPassword: secretMarker + "-not-the-one"})
132	
133		c, _, err := adminFromStore(context.Background(), b.nexus.URL(), b.store)
134		if err != nil {
135			t.Fatalf("adminFromStore: %v", err)
136		}
137		defer c.closeIdle()
138		_, err = b.list(c, dockerProxyRepository)
139	
140		var api *APIError
141		if !errors.As(err, &api) || api.Status != http.StatusUnauthorized {
142			t.Fatalf("listComponents error = %v, want an *APIError with status 401", err)
143		}
144		for _, s := range b.nexus.SecretsSeen() {
145			if s == fakeInitialAdmin {
146				t.Error("the initial admin password was sent to the instance")
147			}
148		}
149		if b.ip.reads != 0 {
150			t.Errorf("the initial password of the pod was read %d time(s)", b.ip.reads)
151		}
152	}
