154	func TestAdminFromStoreWithoutAnAdminPassword(t *testing.T) {
155		tests := []struct {
156			name  string
157			store *Secrets // nil: no file
158		}{
159			{"no secrets file", nil},
160			{"a file that is {}", &Secrets{}},
161			{"only a pending admin password", &Secrets{PendingAdminPassword: secretMarker + "-pending"}},
162			{"only a bench-pull password", &Secrets{PullPassword: secretMarker + "-pull"}},
163		}
164		for _, tt := range tests {
165			t.Run(tt.name, func(t *testing.T) {
166				b := newBench(t)
167				if tt.store != nil {
168					b.store.preset(*tt.store)
169				}
170				c, sec, err := adminFromStore(context.Background(), b.nexus.URL(), b.store)
171				if err == nil {
172					c.closeIdle()
173					t.Fatal("adminFromStore succeeded, want an error")
174				}
175				b.requireQuiet(err)
176				if c != nil {
177					t.Error("a client came back with the error")
178				}
179				if sec != (Secrets{}) {
180					t.Error("secrets came back with the error")
181				}
182				var be *BenchError
183				if !errors.As(err, &be) || be.Kind != ProvisionFailed {
184					t.Fatalf("error = %#v, want a *BenchError of kind ProvisionFailed", err)
185				}
186				if !strings.Contains(be.Check, "mise run nexus-bench:up") {
187					t.Errorf("Check = %q, want it to say to run `mise run nexus-bench:up`", be.Check)
188				}
189				if be.Cause == "" {
190					t.Error("the error has no cause")
191				}
192				if got := len(b.nexus.Requests()); got != 0 {
193					t.Errorf("%d request(s) sent for a bench that was never provisioned", got)
194				}
195				if b.ip.reads != 0 {
196					t.Error("the initial password of the pod was read")
197				}
198			})
199		}
200	}
