202	// failingStore is a SecretStore whose Load fails with an error that carries a password.
203	type failingStore struct{ memStore }
204	
205	func (s *failingStore) Load() (Secrets, bool, error) {
206		return Secrets{}, false, errors.New("read failed near " + secretMarker + "-in-the-error")
207	}
