209	func TestAdminFromStoreUnreadableStore(t *testing.T) {
210		b := newBench(t)
211		store := &failingStore{memStore{log: b.log}}
212		c, _, err := adminFromStore(context.Background(), b.nexus.URL(), store)
213		if err == nil {
214			c.closeIdle()
215			t.Fatal("adminFromStore succeeded, want an error")
216		}
217		var be *BenchError
218		if !errors.As(err, &be) || be.Kind != ProvisionFailed || be.Check == "" {
219			t.Fatalf("error = %#v, want a *BenchError of kind ProvisionFailed with a Check", err)
220		}
221		if strings.Contains(err.Error(), secretMarker) {
222			t.Errorf("the message carries what the store said: %q", err)
223		}
224		if be.Err == nil {
225			t.Error("the cause of the failed read is not kept in Err")
226		}
227	}
