231	func TestListComponentsOnThreePages(t *testing.T) {
232		b := provisioned(t)
233		want := comps("mirror/alpine", "mirror/busybox", "mirror/nginx", "mirror/redis", "mirror/postgres", "mirror/traefik", "mirror/caddy")
234		b.nexus.AddComponents(dockerProxyRepository, want...)
235		b.nexus.SetComponentPageSize(3) // 3 + 3 + 1
236		c := b.adminClient()
237		before := len(b.nexus.Requests())
238	
239		got, err := b.list(c, dockerProxyRepository)
240		if err != nil {
241			t.Fatalf("listComponents: %v", err)
242		}
243		if !reflect.DeepEqual(got, wantComponents(want)) {
244			t.Errorf("components = %+v\nwant %+v", got, wantComponents(want))
245		}
246	
247		reqs := b.requestsFrom(before)
248		if len(reqs) != 3 {
249			t.Fatalf("%d calls, want 3 (one per page): %+v", len(reqs), reqs)
250		}
251		for i, r := range reqs {
252			if r.Method != http.MethodGet || r.Path != pathComponents {
253				t.Errorf("call %d = %s %s, want GET %s", i, r.Method, r.Path, pathComponents)
254			}
255			q, err := url.ParseQuery(r.Query)
256			if err != nil {
257				t.Fatalf("call %d: query %q: %v", i, r.Query, err)
258			}
259			if q.Get("repository") != dockerProxyRepository {
260				t.Errorf("call %d: repository = %q, want %q", i, q.Get("repository"), dockerProxyRepository)
261			}
262			token := q.Get("continuationToken")
263			if (i == 0) != (token == "") {
264				t.Errorf("call %d: continuationToken = %q, want it only from the second call on", i, token)
265			}
266			if r.User != adminUserID {
267				t.Errorf("call %d: user = %q, want %s", i, r.User, adminUserID)
268			}
269		}
270	}
