272	func TestListComponentsPageBoundaries(t *testing.T) {
273		tests := []struct {
274			name      string
275			count     int
276			pageSize  int
277			wantCalls int
278		}{
279			{"an empty repository", 0, 3, 1},
280			{"one page, not full", 2, 3, 1},
281			{"exactly one full page", 3, 3, 1},
282			{"a full page then a short one", 4, 3, 2},
283			{"exactly two full pages", 6, 3, 2},
284			{"one component per page", 3, 1, 3},
285		}
286		for _, tt := range tests {
287			t.Run(tt.name, func(t *testing.T) {
288				b := provisioned(t)
289				names := make([]string, tt.count)
290				for i := range names {
291					names[i] = fmt.Sprintf("mirror/img%d", i)
292				}
293				want := comps(names...)
294				b.nexus.AddComponents(dockerHostedRepository, want...)
295				b.nexus.SetComponentPageSize(tt.pageSize)
296				c := b.adminClient()
297				before := len(b.nexus.Requests())
298	
299				got, err := b.list(c, dockerHostedRepository)
300				if err != nil {
301					t.Fatalf("listComponents: %v", err)
302				}
303				if len(got) != tt.count || (tt.count > 0 && !reflect.DeepEqual(got, wantComponents(want))) {
304					t.Errorf("components = %+v, want %+v", got, wantComponents(want))
305				}
306				if calls := len(b.requestsFrom(before)); calls != tt.wantCalls {
307					t.Errorf("%d calls, want %d", calls, tt.wantCalls)
308				}
309			})
310		}
311	}
