397	func TestListComponentsFailures(t *testing.T) {
398		tests := []struct {
399			name   string
400			status int
401		}{
402			{"403 for an account that may not browse", http.StatusForbidden},
403			{"401 for a password the instance refuses", http.StatusUnauthorized},
404			{"500 from the instance", http.StatusInternalServerError},
405			{"400 for a request it did not understand", http.StatusBadRequest},
406		}
407		for _, tt := range tests {
408			t.Run(tt.name, func(t *testing.T) {
409				b := provisioned(t)
410				b.nexus.AddComponents(dockerProxyRepository, comps("mirror/alpine")...)
411				b.nexus.Forbid(http.MethodGet, pathComponents, tt.status)
412				c := b.adminClient()
413	
414				got, err := b.list(c, dockerProxyRepository)
415				if err == nil {
416					t.Fatalf("listComponents = %+v, want an error", got)
417				}
418				var api *APIError
419				if !errors.As(err, &api) || api.Status != tt.status || api.Op == "" {
420					t.Fatalf("error = %#v, want an *APIError with status %d and an operation", err, tt.status)
421				}
422				if !strings.Contains(api.Op, "component") {
423					t.Errorf("operation %q says nothing about the components", api.Op)
424				}
425				for _, banned := range []string{"://", "continuationToken"} {
426					if strings.Contains(err.Error(), banned) {
427						t.Errorf("message %q contains %q: no URL, no query", err, banned)
428					}
429				}
430				if len(got) != 0 {
431					t.Errorf("components = %+v, want none with an error", got)
432				}
433			})
434		}
435	}
