536	func TestListComponentsHonorsTheContext(t *testing.T) {
537		b := provisioned(t)
538		b.nexus.AddComponents(dockerProxyRepository, comps("a", "b", "c", "d")...)
539		c := b.adminClient()
540		ctx, cancel := context.WithCancel(context.Background())
541		cancel()
542		before := len(b.nexus.Requests())
543		_, err := c.listComponents(ctx, dockerProxyRepository)
544		b.requireQuiet(err)
545		var tr *transportError
546		if !errors.As(err, &tr) || !errors.Is(err, context.Canceled) {
