14	// The tests of adminFromStore and listComponents (DEVDESK-541, NX-02a), run
15	// against the in-memory Nexus of fakenexus_test.go. The signatures are
16	//
17	//	adminFromStore(ctx, baseURL string, store SecretStore) (*client, Secrets, error)
18	//	(*client).listComponents(ctx, repo string) ([]component, error)
19	//
20	// with component{Name, Version, Digest}. Hypotheses to settle with the code or at
21	// step 12 (H-COMPONENTS):
22	//   - a repository the instance does not know (404) lists as no component, without
23	//     an error: the caller compares the list with what it expects, and a repository
24	//     that was just deleted must read as empty;
25	//   - a component without a manifest asset has an empty Digest, never an error;
26	//   - adminFromStore sends no request: a stored password the instance refuses shows
27	//     on the first call as an *APIError, and the initial password is never tried;
28	//   - a store without an admin password is a *BenchError of kind ProvisionFailed
29	//     whose Check says to run `mise run nexus-bench:up`; a pending password alone
30	//     is not a current one.
31	
32	const (
33		digestAlpine = "sha256:" + "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
34		digestBusy   = "sha256:" + "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
35		digestNginx  = "sha256:" + "fedcba9876543210fedcba9876543210fedcba9876543210fedcba9876543210"
36	
37		// maxComponentRequests bounds a listing that never ends: whatever the way the
38		// client stops it, it does so within this many calls.
39		maxComponentRequests = 1000
40	)
