42	// provisioned is a bench whose admin password is stored and whose repositories
43	// exist, as `up` leaves it.
44	func provisioned(t *testing.T) *bench {
45		t.Helper()
46		b := newBench(t).withKnownAdmin()
47		b.mustRun()
48		return b
49	}
50	
51	// adminClient builds the client of the stored admin and closes it with the test.
52	func (b *bench) adminClient() *client {
53		b.t.Helper()
54		ctx, cancel := context.WithTimeout(context.Background(), provisionTimeout)
55		defer cancel()
56		c, _, err := adminFromStore(ctx, b.nexus.URL(), b.store)
57		if err != nil {
58			b.t.Fatalf("adminFromStore: %v", err)
59		}
60		b.t.Cleanup(c.closeIdle)
61		return c
62	}
63	
64	// list calls listComponents and checks the error text is quiet.
65	func (b *bench) list(c *client, repo string) ([]component, error) {
66		b.t.Helper()
67		ctx, cancel := context.WithTimeout(context.Background(), provisionTimeout)
68		defer cancel()
69		got, err := c.listComponents(ctx, repo)
70		b.requireQuiet(err)
71		return got, err
72	}
