74	func comps(names ...string) []fakeComponent {
75		out := make([]fakeComponent, 0, len(names))
76		for i, n := range names {
77			out = append(out, fakeComponent{Name: n, Version: fmt.Sprintf("v%d", i+1), Digest: fmt.Sprintf("sha256:%064x", i+1)})
78		}
79		return out
80	}
81	
82	func wantComponents(in []fakeComponent) []component {
83		out := make([]component, 0, len(in))
84		for _, c := range in {
85			out = append(out, component{Name: c.Name, Version: c.Version, Digest: c.Digest})
86		}
87		return out
88	}
