264				t.Errorf("call %d: continuationToken = %q, want it only from the second call on", i, token)
265			}
266			if r.User != adminUserID {
267				t.Errorf("call %d: user = %q, want %s", i, r.User, adminUserID)
268			}
269		}
270	}
