16	const (
17		// clientTimeout bounds every REST call, connection included.
18		clientTimeout = 15 * time.Second
19		// maxResponseBytes is the most the client reads from one answer. A larger
20		// one is an error, and its content is never decoded.
21		maxResponseBytes = 1 << 20
22		// drainBytes is how much of an unwanted answer is read so the connection
23		// can be reused.
24		drainBytes = 4 << 10
