26	
27	// APIError is a REST call the instance answered with a status outside 2xx. It
28	// carries the operation and the status only: no URL, no request body, no answer
29	// body, because any of them could hold a credential.
30	type APIError struct {
31		// Op says what the call was for, e.g. "create user bench-pull".
32		Op     string
33		Status int
34		// RemoteURLBlocked is true for a 400 whose validation errors name
35		// proxy.remoteUrl: Nexus 3.98.1 resolves the host of a proxy's remote URL
36		// when it saves the repository and refuses one that does not resolve. Only
37		// this verdict is kept, never the text of the answer.
38		RemoteURLBlocked bool
39	}
40	
41	// Error returns "<Op>: HTTP <status> <text>".
42	func (e *APIError) Error() string {
43		return strings.TrimSpace(fmt.Sprintf("%s: HTTP %d %s", e.Op, e.Status, http.StatusText(e.Status)))
44	}
45	
46	// transportError is a call that got no answer: connection refused, reset,
47	// timeout. The cause stays in Err; its text carries the URL and is not printed.
48	type transportError struct {
49		Op  string
50		Err error
51	}
52	
53	func (e *transportError) Error() string { return "no answer to " + e.Op }
54	func (e *transportError) Unwrap() error { return e.Err }
55	
56	// tooLargeError is an answer past maxResponseBytes.
57	type tooLargeError struct{ Op string }
58	
59	func (e *tooLargeError) Error() string {
60		return fmt.Sprintf("the answer to %s is larger than %d bytes", e.Op, maxResponseBytes)
61	}
62	
63	// decodeError is an answer that is not the JSON the client expects.
64	type decodeError struct {
65		Op  string
66		Err error
67	}
68	
69	func (e *decodeError) Error() string { return "unexpected answer to " + e.Op }
70	func (e *decodeError) Unwrap() error { return e.Err }
71	
72	// client is the REST client of one Nexus instance. It follows no redirection
73	// (an answer that moves the call elsewhere would carry the credentials with
74	// it), reads at most maxResponseBytes of an answer, and never logs a header.
75	type client struct {
76		base     string
77		user     string
78		REDACTED string
79		http     *http.Client
80	}
81	
82	// newClient returns a client for baseURL, authenticating with Basic auth as user
83	// unless user is empty (the calls that need no account).
84	func newClient(baseURL, user, REDACTED string) *client {
85		transport := http.DefaultTransport.(*http.Transport).Clone()
86		// The bench is reached directly: a proxy named by the environment would
87		// receive the credentials.
88		transport.Proxy = nil
89		return &client{
90			base:     strings.TrimRight(baseURL, "/"),
91			user:     user,
92			REDACTED: REDACTED,
93			http: &http.Client{
94				Timeout:       clientTimeout,
95				Transport:     transport,
96				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
97			},
98		}
99	}
100	
101	// closeIdle drops the connections the client keeps open.
102	func (c *client) closeIdle() { c.http.CloseIdleConnections() }
103	
104	// request is one REST call.
105	type request struct {
106		op          string
107		method      string
108		path        string
109		query       url.Values
110		contentType string
111		body        []byte
112	}
113	
114	// response is what the instance answered.
115	type response struct {
116		status int
117		header http.Header
118		body   []byte
119		// remoteURLBlocked is the verdict of remoteURLRefused on a 400; the body of
120		// an answer outside 2xx is read for it and dropped.
121		remoteURLBlocked bool
122	}
123	
124	// do sends r and returns the answer whatever its status. The error is a
125	// *transportError or a *tooLargeError.
126	func (c *client) do(ctx context.Context, r request) (response, error) {
127		target := c.base + r.path
128		if len(r.query) > 0 {
129			target += "?" + r.query.Encode()
130		}
131		var body io.Reader
132		if r.body != nil {
133			body = bytes.NewReader(r.body)
134		}
135		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
136		if err != nil {
137			return response{}, &transportError{Op: r.op, Err: err}
138		}
139		req.Header.Set("Accept", "application/json")
140		if r.contentType != "" {
141			req.Header.Set("Content-Type", r.contentType)
142		}
143		if c.user != "" {
144			req.SetBasicAuth(c.user, c.REDACTED)
145		}
146		resp, err := c.http.Do(req)
147		if err != nil {
148			return response{}, &transportError{Op: r.op, Err: err}
149		}
150		defer func() { _ = resp.Body.Close() }()
151		if resp.StatusCode < 200 || resp.StatusCode > 299 {
152			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
153			return response{
154				status: resp.StatusCode, header: resp.Header,
155				remoteURLBlocked: resp.StatusCode == http.StatusBadRequest && remoteURLRefused(refused),
156			}, nil
157		}
158		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
159		if err != nil {
160			return response{}, &transportError{Op: r.op, Err: err}
161		}
162		if len(data) > maxResponseBytes {
163			return response{}, &tooLargeError{Op: r.op}
164		}
165		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
166	}
167	
168	// expect sends r and turns a status outside 2xx into an *APIError.
169	func (c *client) expect(ctx context.Context, r request) (response, error) {
170		resp, err := c.do(ctx, r)
171		if err != nil {
172			return resp, err
173		}
174		if resp.status < 200 || resp.status > 299 {
175			return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked}
176		}
177		return resp, nil
178	}
179	
180	// remoteURLRefused reports whether body is a Nexus validation error list with
181	// an entry on proxy.remoteUrl whose message says the host did not resolve:
182	// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
183	// Only that verdict leaves the function: no text of the answer is kept. The
184	// content type of the answer is vendor specific, so only the JSON is read; a
185	// body past drainBytes was cut and is not trusted.
186	func remoteURLRefused(body []byte) bool {
187		if len(body) > drainBytes {
188			return false
189		}
190		var errs []validationError
191		if err := json.Unmarshal(body, &errs); err != nil {
192			return false
193		}
194		return slices.ContainsFunc(errs, func(e validationError) bool {
195			return strings.HasSuffix(e.ID, "proxy.remoteUrl") &&
196				strings.Contains(strings.ToLower(e.Message), "resolve host")
197		})
198	}
199	
200	// validationError is one entry of a Nexus validation error list. The message is
201	// only matched by remoteURLRefused, never stored or shown.
202	type validationError struct {
203		ID      string `json:"id"`
204		Message string `json:"message"`
205	}
206	
207	// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
208	// is found == false without an error.
209	func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
210		resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
211		if err != nil {
212			return false, err
213		}
214		switch {
215		case resp.status == http.StatusNotFound:
216			return false, nil
217		case resp.status < 200 || resp.status > 299:
218			return false, &APIError{Op: op, Status: resp.status}
219		}
220		if out == nil {
221			return true, nil
222		}
223		if err := json.Unmarshal(resp.body, out); err != nil {
224			return false, &decodeError{Op: op, Err: err}
225		}
226		return true, nil
227	}
228	
229	// read is get for an object that has to exist: a 404 is an *APIError.
230	func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
231		found, err := c.get(ctx, op, path, query, out)
232		if err != nil {
233			return err
234		}
235		if !found {
236			return &APIError{Op: op, Status: http.StatusNotFound}
237		}
238		return nil
239	}
240	
241	// write sends payload as JSON with method and expects a 2xx.
242	func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
243		data, err := json.Marshal(payload)
244		if err != nil {
245			return &decodeError{Op: op, Err: err}
246		}
247		_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
248		return err
249	}
