99		// Seed reads the Deployment and the pods of the upstream, scales it back
100		// when it is cut, and reaches it through a port-forward, which gets the
101		// Service, then the pod it picks, before it opens the tunnel.
102		OpSeed: {
103			{"get", "deployments", scopeNamespace},
104			{"list", "pods", scopeNamespace},
105			{"get", "pods", scopeNamespace},
