112	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
113	// returns what it learned. Nothing is written to the cluster, whatever the
114	// outcome: a failure here means no write was ever issued. The checks run in a
115	// fixed order and stop at the first failure, so nothing is asked of a cluster
116	// the context does not reach:
117	//
118	//  1. the parameters (no call at all)
119	//  2. the context is in the kubeconfig
120	//  3. the API server answers /readyz
121	//  4. the can-i questions of the operation
122	//  5. the namespace: absent, ours, or foreign
123	//  6. up only: no other Service holds one of our NodePorts
124	//  7. all but down: the InternalIP of the node
125	//
126	// Every failure is a *BenchError.
127	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
128		var res PreflightResult
129		if err := p.Validate(); err != nil {
130			return res, err
131		}
132		pf := preflight{r: r, p: p}
133		if err := pf.checkContext(ctx); err != nil {
134			return res, err
135		}
136		if err := pf.checkReachable(ctx); err != nil {
137			return res, err
138		}
139		for _, perm := range permissionsByOp[op] {
140			if err := pf.checkPermission(ctx, perm); err != nil {
141				return res, err
142			}
143		}
144		res, err := pf.checkNamespace(ctx, op)
145		if err != nil {
146			return res, err
147		}
148		if op == OpUp {
149			if err := pf.checkNodePorts(ctx); err != nil {
150				return res, err
151			}
152		}
153		if op != OpDown {
154			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
155				return res, err
156			}
157		}
158		return res, nil
159	}
160	
161	type preflight struct {
162		r Runner
163		p Params
164	}
165	
166	// local runs a call that does not reach the API server.
167	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
168		out, errOut, err := pf.r.Run(ctx, nil, args...)
169		return string(out), string(errOut), err
170	}
171	
172	// remote runs a call that reaches the API server, under a request timeout.
173	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
174		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
175	}
