183	// the stderr. Neither the stderr nor the sub-process error reaches the message.
184	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
185		kind := classifyKubectl(stderr)
186		reason := "kubectl failed"
187		switch kind {
188		case Forbidden:
189			reason = "the API server refused the request (forbidden)"
190		case ClusterUnreachable:
191			reason = "the cluster did not answer"
192		}
193		return &BenchError{
194			Kind:  kind,
195			Cause: "could not " + what + ": " + reason,
196			Check: pf.command(args...),
197			Err:   err,
198		}
