204		if err != nil {
205			return pf.failure("list the kubeconfig contexts", args, errOut, err)
206		}
207		for _, line := range strings.Split(out, "\n") {
208			if strings.TrimSpace(line) == pf.p.Context {
209				return nil
210			}
211		}
212		return &BenchError{
213			Kind:  ContextNotFound,
214			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
215			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
216		}
