219	func (pf preflight) checkReachable(ctx context.Context) error {
220		args := []string{"get", "--raw", "/readyz"}
221		_, errOut, err := pf.remote(ctx, args...)
222		if err == nil {
223			return nil
224		}
225		// A refusal (an expired token, a 403) is not an absent cluster: say so.
226		// Anything else, classified or not, means the server did not answer.
227		if classifyKubectl(errOut) == Forbidden {
228			return pf.failure("reach the API server", args, errOut, err)
229		}
230		return &BenchError{
231			Kind:  ClusterUnreachable,
232			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
233			Check: pf.command(args...),
234			Err:   err,
235		}
