238	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
239	// non-zero exit, so the answer is read before the error.
240	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
241		args := []string{"auth", "can-i", perm.verb, perm.resource}
242		where := "cluster-wide"
243		switch perm.scope {
244		case scopeNamespace:
245			args = append(args, "-n", pf.p.Namespace)
246			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
247		case scopeAll:
248			args = append(args, "-A")
249			where = "in all namespaces"
250		}
251		out, errOut, err := pf.remote(ctx, args...)
252		answer := strings.TrimSpace(out)
253		switch {
254		case strings.HasPrefix(answer, "no"):
255			return &BenchError{
256				Kind:  Forbidden,
257				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
258				Check: pf.command(args...),
259				Err:   err,
260			}
261		case err == nil && strings.HasPrefix(answer, "yes"):
262			return nil
263		}
264		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
265	}
